{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Hydroxysafflor yellow A, a large polar glycoside, reached 1026 ng/g in rat brain after systemic administration, directly demonstrating that high-TPSA glycosides can achieve meaningful CNS access despite unfavorable passive diffusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Picroside-I, an iridoid glycoside, rapidly penetrated the BBB and was detected in rat brain tissue, supporting CNS access for glycoside-containing natural products.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Isovitexin, a flavonoid C-glucoside, was detected in rat brain at 14.74 ng/mL after i.v. dosing, confirming brain transfer for a polar glycoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Kanamycin, a highly polar aminoglycoside, appeared in CSF in concentrations related to blood levels, showing that very polar sugar-containing molecules can access CNS compartments.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "NS1209, a polar ionizable molecule, was detected in human CSF for up to 24 h with a CSF half-life of ~10 h, demonstrating meaningful CNS exposure after systemic infusion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Lorlatinib achieved CSF/free plasma ratios of 0.61-0.96 in patients, illustrating that high CNS exposure is achievable and supporting the positive endpoint definition.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer experimental analogues—especially polar glycosides and sugar-containing molecules—show measurable brain/CSF penetration after systemic administration. Under brain tumor/glioma conditions with BBB disruption, the query anthracycline glycoside is expected to achieve meaningful CNS access despite an unfavorable passive-diffusion prior.",
  "evidence_gaps": [
    "No direct brain/CSF pharmacokinetic data for the query anthracycline itself.",
    "Efflux transporter liability (P-gp/BCRP) may reduce unbound brain concentrations.",
    "Brain tumor BBB disruption is heterogeneous and may limit delivery to tumor core.",
    "Quantitative brain-to-plasma ratio for the query is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

